SELECT (SELECT group_concat(type||':'||name||':'||tbl_name,'|') FROM (SELECT type,name,tbl_name FROM sqlite_schema WHERE name NOT LIKE 'sqlite_%' ORDER BY type,name)), (SELECT group_concat(cid||':'||name||':'||type||':'||"notnull"||':'||coalesce(dflt_value,'NULL')||':'||pk,'|') FROM (SELECT cid,name,type,"notnull",dflt_value,pk FROM pragma_table_info('t1') ORDER BY cid)), (SELECT group_concat(cid||':'||name||':'||type||':'||"notnull"||':'||coalesce(dflt_value,'NULL')||':'||pk,'|') FROM (SELECT cid,name,type,"notnull",dflt_value,pk FROM pragma_table_info('t2') ORDER BY cid)), (SELECT wr FROM pragma_table_list WHERE schema='main' AND name='t1'), (SELECT wr FROM pragma_table_list WHERE schema='main' AND name='t2')